const cfg = $getWorkflowStaticData('global');
if (!cfg._initialized) {
  cfg.BYBIT_API_KEY = 'YOUR_BYBIT_API_KEY';
  cfg.BYBIT_API_SECRET = 'YOUR_BYBIT_API_SECRET';
  cfg.BYBIT_TESTNET = 'false';
  cfg.TELEGRAM_CHAT_ID = '543663073';
  cfg._initialized = true;
}
return [{ json: { status: 'ok' } }];

// =============================================
// Collect Analytics from global static data
// =============================================
const cfg = $getWorkflowStaticData('global');

// Get today's date in Moscow timezone (UTC+3)
const now = new Date();
const msk = new Date(now.getTime() + 3 * 60 * 60 * 1000);
const dateKey = msk.toISOString().slice(0, 10); // YYYY-MM-DD

// Read analytics for today
const analyticsKey = `analytics_${dateKey}`;
const analytics = cfg[analyticsKey] || {};

// Scanning stats
const pairsChecked = analytics.pairs_checked || 0;
const pairsPassedVolume = analytics.pairs_passed_volume || 0;

// Claude analysis stats
const pairsSentToClaude = analytics.pairs_sent_to_claude || 0;
const signalsReceived = analytics.signals_received || 0;
const signalsRejected = analytics.signals_rejected || 0;

// Rejection reasons breakdown
const rejections = analytics.rejection_reasons || {};
const weakLevel = rejections.weak_level || 0;
const lowConfidence = rejections.low_confidence || 0;
const lowRR = rejections.low_rr || 0;
const tfMisalignment = rejections.tf_misalignment || 0;
const againstTrend = rejections.against_trend || 0;

// Active signals
const activeSignals = analytics.active_signals || [];
const signalsTaken = activeSignals.length;

return [{
  json: {
    dateKey,
    pairsChecked,
    pairsPassedVolume,
    pairsSentToClaude,
    signalsReceived,
    signalsRejected,
    weakLevel,
    lowConfidence,
    lowRR,
    tfMisalignment,
    againstTrend,
    signalsTaken,
    activeSignals
  }
}];

