function hmacSHA256(ks,ms){const toB=s=>Array.from(s).map(c=>c.charCodeAt(0));let k=toB(ks);if(k.length>64)k=sha256(k);while(k.length<64)k.push(0);return sha256([...k.map(b=>b^0x5c),...sha256([...k.map(b=>b^0x36),...toB(ms)])]).map(b=>b.toString(16).padStart(2,'0')).join('');}
// =============================================
// Get Balance & Positions from Bybit
// =============================================
const cfg = $getWorkflowStaticData('global');
const analyticsData = $input.first().json;

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = hmacSHA256(apiSecret, preSign);
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

// Get wallet balance
let totalEquity = 0;
try {
  const balResp = await signedGet.call(this, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
  totalEquity = parseFloat(balResp.result.list[0].totalEquity);
} catch(e) {}

// Get open positions
let openPositions = [];
try {
  const posResp = await signedGet.call(this, '/v5/position/list', {
    category: 'linear', settleCoin: 'USDT'
  });
  if (posResp.retCode === 0) {
    openPositions = (posResp.result?.list || []).filter(p => parseFloat(p.size) > 0);
  }
} catch(e) {}

// Get closed P&L for today
const today = new Date();
today.setHours(0, 0, 0, 0);
const startTime = today.getTime().toString();

let dailyPnl = 0;
try {
  const pnlResp = await signedGet.call(this, '/v5/position/closed-pnl', {
    category: 'linear', startTime, limit: '100'
  });
  if (pnlResp.retCode === 0) {
    dailyPnl = (pnlResp.result?.list || []).reduce((sum, p) => sum + parseFloat(p.closedPnl), 0);
  }
} catch(e) {}

// Add unrealized P&L
const unrealizedPnl = openPositions.reduce((sum, p) => sum + parseFloat(p.unrealisedPnl || 0), 0);
const totalDailyPnl = dailyPnl + unrealizedPnl;
const dailyLossPercent = totalEquity > 0 ? Math.abs(Math.min(totalDailyPnl, 0)) / totalEquity * 100 : 0;

return [{
  json: {
    ...analyticsData,
    totalEquity,
    openPositions: openPositions.length,
    maxPositions: parseInt(cfg.MAX_OPEN_POSITIONS || '3'),
    dailyPnl: totalDailyPnl.toFixed(2),
    dailyPnlPercent: totalEquity > 0 ? (totalDailyPnl / totalEquity * 100).toFixed(2) : '0.00',
    dailyLossUsed: dailyLossPercent.toFixed(2),
    maxDailyLoss: parseFloat(cfg.MAX_DAILY_LOSS || '3')
  }
}];

// =============================================
// Format Telegram Report
// =============================================
const data = $input.first().json;

// Moscow time (UTC+3)
const now = new Date();
const msk = new Date(now.getTime() + 3 * 60 * 60 * 1000);
const dateStr = msk.toISOString().slice(0, 10);
const timeStr = msk.toISOString().slice(11, 16);

// Calculate minutes until next scan (4h interval)
const mskMinutes = msk.getUTCHours() * 60 + msk.getUTCMinutes();
const intervalMin = 240; // 4 hours
const nextScanMin = intervalMin - (mskMinutes % intervalMin);

let msg = `📊 ОТЧЁТ БОТА — ${dateStr}, ${timeStr} (MSK)\n\n`;

msg += `🔍 СКАНИРОВАНИЕ:\n`;
msg += `• Пар проверено: ${data.pairsChecked}\n`;
msg += `• Пар прошло фильтр объёма (>$50M): ${data.pairsPassedVolume}\n\n`;

msg += `🧠 АНАЛИЗ CLAUDE:\n`;
msg += `• Пар отправлено на анализ: ${data.pairsSentToClaude}\n`;
msg += `• Сигналов получено: ${data.signalsReceived}\n`;
msg += `• Отклонено: ${data.signalsRejected}\n\n`;

msg += `❌ ПРИЧИНЫ ОТКЛОНЕНИЯ:\n`;
msg += `• Слабый уровень (weak): ${data.weakLevel}\n`;
msg += `• Таймфреймы не совпадают: ${data.tfMisalignment}\n`;
msg += `• R:R ниже 1:3: ${data.lowRR}\n`;
msg += `• Confidence ниже 75: ${data.lowConfidence}\n`;
msg += `• Против тренда старшего ТФ: ${data.againstTrend}\n\n`;

msg += `✅ ВЗЯТО В РАБОТУ: ${data.signalsTaken}\n`;
if (data.activeSignals && data.activeSignals.length > 0) {
  data.activeSignals.forEach((s, i) => {
    msg += `\n<b>${i + 1}. ${s.pair || s.symbol}</b> ${s.direction || s.side}\n`;
    msg += `   Entry: ${s.entry || s.entry_price} | SL: ${s.sl || s.stop_loss} | TP: ${s.tp || s.take_profit}\n`;
    msg += `   Уровень: ${s.level_strength || '-'} | R:R ${s.rr || s.risk_reward || '-'} | Conf: ${s.confidence || '-'}%\n`;
    msg += `   ${s.reasoning || ''}\n`;
  });
} else {
  msg += `Нет сигналов, все пары отклонены\n`;
}

msg += `\n📈 ОТКРЫТЫЕ ПОЗИЦИИ: ${data.openPositions} из ${data.maxPositions}\n`;
msg += `📉 P&L СЕГОДНЯ: $${data.dailyPnl} (${data.dailyPnlPercent}%)\n`;
msg += `💰 БАЛАНС: $${parseFloat(data.totalEquity).toFixed(2)}\n`;
msg += `🛡 ДНЕВНОЙ ЛИМИТ ПОТЕРЬ: использовано ${data.dailyLossUsed}% из ${data.maxDailyLoss}%\n`;
msg += `⏱ Следующее сканирование: через ${nextScanMin} мин`;

return [{ json: { message: msg } }];
